package com.vulpine.mcb.body;

import com.google.gson.Gson;
import com.google.gson.JsonParser;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

/** Runs the exact maps and policies generated by scripts/analysis/route_differential.py. */
public final class RouteDifferential {
    private record Key(int x,int y,int z) { }
    private static RoutePlanner.Node node(com.google.gson.JsonArray a) {
        return new RoutePlanner.Node(a.get(0).getAsInt(),a.get(1).getAsDouble(),a.get(2).getAsInt());
    }
    public static void main(String[] args) throws Exception {
        var gson=new Gson(); var cases=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray();
        for(var entry:cases) {
            var c=entry.getAsJsonObject(); var opt=c.getAsJsonObject("options");
            var palette=c.getAsJsonArray("palette"); var cells=new HashMap<Key,Map<String,Object>>();
            for(var row:c.getAsJsonArray("cells")) { var a=row.getAsJsonArray();
                cells.put(new Key(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt()),gson.fromJson(palette.get(a.get(3).getAsInt()),Map.class)); }
            var threats=new ArrayList<double[]>(); for(var row:c.getAsJsonArray("threats")) { var a=row.getAsJsonArray(); threats.add(new double[]{a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble()}); }
            var planner=new RoutePlanner((x,y,z)->cells.get(new Key(x,y,z)),node(c.getAsJsonArray("start")),node(c.getAsJsonArray("goal")),0,1,opt.get("sprint").getAsBoolean(),
                    opt.get("unknown").getAsBoolean()?2:0)
                    .withPolicy(opt.get("ticks").getAsBoolean(),opt.get("search").getAsBoolean(),opt.get("bdiag").getAsBoolean(),opt.get("diag").getAsBoolean(),opt.get("shapes").getAsBoolean(),1)
                    .withSurvival(opt.get("hazard").getAsDouble(),opt.get("mob").getAsDouble(),3,threats);
            if(!c.get("reach").isJsonNull()) planner.withInteraction(c.get("reach").getAsDouble());
            var result=planner.search(10000); var out=new LinkedHashMap<String,Object>();
            out.put("id",c.get("id").getAsString()); out.put("status",result.status());
            out.put("route",result.route().stream().map(p->List.of(p.x(),p.y(),p.z())).toList());
            out.put("expanded",result.expanded()); out.put("cost",result.cost());
            System.out.println(gson.toJson(out));
        }
    }
}
